constexpr qsizetype maxInput=536870912;
constexpr qsizetype maxPacket=16*1024*1024;
using BytesResult=Result<QByteArray>;
quint16 be16(const char* p){return qFromBigEndian<quint16>(p);} quint32 be32(const char* p){return qFromBigEndian<quint32>(p);}
void put16(QByteArray& b,quint16 v){char p[2];qToLittleEndian(v,p);b.append(p,2);}void put32(QByteArray& b,quint32 v){char p[4];qToLittleEndian(v,p);b.append(p,4);}void putBe16(QByteArray& b,quint16 v){char p[2];qToBigEndian(v,p);b.append(p,2);}void putBe32(QByteArray& b,quint32 v){char p[4];qToBigEndian(v,p);b.append(p,4);}
quint32 crc32(const QByteArray& b){quint32 c=0xffffffff;for(unsigned char v:b){c^=v;for(int k=0;k<8;++k)c=(c>>1)^((c&1)?0xedb88320u:0);}return c^0xffffffff;}
BytesResult readBytes(const QString& path){QFile f(path);if(!f.exists())return BytesResult::failure(ErrorCode::FileNotFound,"Archivo inexistente",path);if(!f.open(QIODevice::ReadOnly))return BytesResult::failure(ErrorCode::FileReadError,"No se pudo leer el archivo",f.errorString());if(f.size()>maxInput)return BytesResult::failure(ErrorCode::ImageDimensionsTooLarge,"Archivo demasiado grande para procesar metadatos (512 MiB)");auto b=f.readAll();if(f.error()!=QFileDevice::NoError)return BytesResult::failure(ErrorCode::FileReadError,"Error leyendo metadatos",f.errorString());return BytesResult::success(b);}
struct Segment{QByteArray type,data,raw;};
// Strict container parsing; JPEG scan data is an opaque final segment, preserving compression exactly.
bool splitJpeg(const QByteArray& b,std::vector<Segment>& parts){if(!b.startsWith(QByteArray::fromHex("ffd8")))return false;qsizetype p=2;while(p<b.size()){qsizetype start=p;if(quint8(b[p++])!=255)return false;while(p<b.size() && quint8(b[p])==255)++p;if(p>=b.size())return false;int m=quint8(b[p++]);if(m==0xda || m==0xd9){parts.push_back({"SCAN",{},b.mid(start)});return true;}if(m==0x01 || (m>=0xd0 && m<=0xd7)){parts.push_back({QByteArray(1,char(m)),{},b.mid(start,p-start)});continue;}if(p+2>b.size())return false;quint16 n=be16(b.constData()+p);if(n<2 || p+n>b.size())return false;parts.push_back({QByteArray(1,char(m)),b.mid(p+2,n-2),b.mid(start,p+n-start)});p+=n;}return false;}
bool splitPng(const QByteArray& b,std::vector<Segment>& parts){if(!b.startsWith(QByteArray::fromHex("89504e470d0a1a0a")))return false;qsizetype p=8;while(p+12<=b.size()){quint32 n=be32(b.constData()+p);if(quint64(n)+12>quint64(b.size()-p))return false;auto type=b.mid(p+4,4),data=b.mid(p+8,n);if(crc32(type+data)!=be32(b.constData()+p+8+n))return false;parts.push_back({type,data,b.mid(p,n+12)});p+=n+12;if(type=="IEND")return n==0 && p==b.size();}return false;}
bool splitWebp(const QByteArray& b,std::vector<Segment>& parts){if(b.size()<12 || b.left(4)!="RIFF" || b.mid(8,4)!="WEBP" || quint64(qFromLittleEndian<quint32>(b.constData()+4))+8!=quint64(b.size()))return false;qsizetype p=12;while(p+8<=b.size()){quint32 n=qFromLittleEndian<quint32>(b.constData()+p+4);quint64 total=8+quint64(n)+(n&1);if(total>quint64(b.size()-p))return false;parts.push_back({b.mid(p,4),b.mid(p+8,n),b.mid(p,qsizetype(total))});p+=qsizetype(total);}return p==b.size();}
QByteArray jpegSegment(int marker,const QByteArray& data){QByteArray b;b.append(char(255));b.append(char(marker));putBe16(b,quint16(data.size()+2));b+=data;return b;}
QByteArray pngChunk(const QByteArray& type,const QByteArray& data){QByteArray b;putBe32(b,quint32(data.size()));b+=type;b+=data;putBe32(b,crc32(type+data));return b;}
QByteArray riffChunk(const QByteArray& type,const QByteArray& data){QByteArray b=type;put32(b,quint32(data.size()));b+=data;if(data.size()&1)b.append(char(0));return b;}
// Bounded RFC 1950/1951 decoder: metadata compression must not bypass allocation limits.
