    struct Huffman{std::array<int,16> count{};std::vector<int> symbols;bool valid{true};
        explicit Huffman(const std::vector<int>& lengths){for(int n:lengths){if(n<0||n>15){valid=false;return;}if(n)++count[n];}int left=1;for(int i=1;i<=15;++i){left=(left<<1)-count[i];if(left<0){valid=false;return;}}for(int i=1;i<=15;++i)for(size_t s=0;s<lengths.size();++s)if(lengths[s]==i)symbols.push_back(int(s));}
    };
