        if(type==1){literal.resize(288);for(int i=0;i<288;++i)literal[i]=i<144?8:i<256?9:i<280?7:8;distance.assign(32,5);}
        else if(type==2){int nl=int(take(5))+257,nd=int(take(5))+1,nc=int(take(4))+4;if(nl>286)return bad();// RFC 1951 code-length alphabet order.
            static const int codeOrder[]{16,17,18,0,8,7,9,6,10,5,11,4,12,3,13,2,14,1,15};
            std::vector<int> lengths(19);for(int i=0;i<nc;++i)lengths[codeOrder[i]]=int(take(3));Huffman ch(lengths);std::vector<int> all;
            while(ok&&int(all.size())<nl+nd){int symbol=decode(ch);if(!ok)return bad();if(symbol<=15)all.push_back(symbol);else{int repeat=0,value=0;if(symbol==16){if(all.empty())return bad();value=all.back();repeat=int(take(2))+3;}else if(symbol==17)repeat=int(take(3))+3;else if(symbol==18)repeat=int(take(7))+11;else return bad();if(int(all.size())+repeat>nl+nd)return bad();all.insert(all.end(),size_t(repeat),value);}}
            if(!ok)return bad();literal.assign(all.begin(),all.begin()+nl);distance.assign(all.begin()+nl,all.end());
        }else return bad();
