    explicit Tiff(const QByteArray& bytes,QStringList* w=nullptr):b(bytes),warnings(w){valid=b.size()>=8 && (b.left(2)=="II" || b.left(2)=="MM");little=b.left(2)=="II";valid=valid && u16(2)==42;}
    bool range(quint64 p,quint64 n)const{return p<=quint64(b.size()) && n<=quint64(b.size())-p;}
    quint16 u16(quint64 p)const{return range(p,2)?(little?qFromLittleEndian<quint16>(b.constData()+p):be16(b.constData()+p)):0;}
    quint32 u32(quint64 p)const{return range(p,4)?(little?qFromLittleEndian<quint32>(b.constData()+p):be32(b.constData()+p)):0;}
    int unit(quint16 type)const{switch(type){case 1:case 2:case 6:case 7:return 1;case 3:case 8:return 2;case 4:case 9:case 11:return 4;case 5:case 10:case 12:return 8;default:return 0;}}
    quint64 length(quint32 e)const{return quint64(unit(u16(e+2)))*u32(e+4);}
    quint32 dataOffset(quint32 e)const{return length(e)<=4?e+8:u32(e+8);}
